Below is the implementation of each component of the filter engine, illustrating how initialization, statistical tracking, filling resolution, and multi-gate validation work together.
1. Constructor and Destructor Implementation
The constructor validates input parameters, configures operational limits, validates rollover minute boundaries via SetRolloverWindow(), allocates the circular ring buffer for historical spread data, and resets all telemetry counters. It enforces a minimum baseline period of 10 observations so that the rolling buffer capacity matches the Z-score activation condition, while the destructor explicitly releases the internal buffer when the instance is destroyed:
//+------------------------------------------------------------------+
//| Constructor: Parameter validation and ring buffer allocation     |
//+------------------------------------------------------------------+
CExecutionFilter::CExecutionFilter(
const
string
symbol,
const
long
hard_cap,
const
double
zscore_limit,
const
int
baseline_period,
const
int
rollover_start,
const
int
rollover_end,
const
uint
max_quote_age)
  {
//--- Validate input parameters and assign member variables
m_symbol              = (symbol ==
""
) ?
_Symbol
: symbol;
   m_spread_hard_cap     = (hard_cap >
0
) ? hard_cap :
40
;
   m_spread_zscore_limit = (zscore_limit >
0.0
) ? zscore_limit :
2.0
;
   m_baseline_period     = (baseline_period >=
10
) ? baseline_period :
30
;
   SetRolloverWindow(rollover_start, rollover_end);
   m_max_quote_age_ms    = (max_quote_age >
0
) ? max_quote_age :
3000
;
//--- Enable default safety gates
m_enable_rollover_gate  =
true
;
   m_enable_spread_gate    =
true
;
   m_enable_freshness_gate =
true
;
   m_enable_filling_gate   =
true
;
//--- Allocate static ring buffer
m_buffer_count =
0
;
   m_buffer_idx   =
0
;
ArrayResize
(m_spread_buffer, m_baseline_period);
ArrayInitialize
(m_spread_buffer,
0
);

   ResetTelemetry();
  }
//+------------------------------------------------------------------+
//| Destructor: Clean dynamically allocated array resources          |
//+------------------------------------------------------------------+
CExecutionFilter::~CExecutionFilter(
void
)
  {
//--- Release internal buffer storage
ArrayFree
(m_spread_buffer);
  }
2. Statistical Baseline Tracking
To maintain a historical spread distribution free from outlier distortion, UpdateSpreadBuffer writes approved spread observations into the circular buffer and advances the write index. ComputeSpreadStats then calculates the arithmetic mean and sample standard deviation (using N - 1 degrees of freedom) across the active sample count:
//+------------------------------------------------------------------+
//| Appends verified spread sample to internal ring buffer           |
//+------------------------------------------------------------------+
void
CExecutionFilter::UpdateSpreadBuffer(
const
long
current_spread)
  {
//--- Write to current index and advance circular pointer
m_spread_buffer[m_buffer_idx] = current_spread;
   m_buffer_idx = (m_buffer_idx +
1
) % m_baseline_period;
if
(m_buffer_count < m_baseline_period)
     {
//--- Increment count until buffer capacity is reached
m_buffer_count++;
     }
  }
//+------------------------------------------------------------------+
//| Computes baseline mean and sample standard deviation             |
//+------------------------------------------------------------------+
void
CExecutionFilter::ComputeSpreadStats(
double
&mean,
double
&std_dev)
const
{
//--- Guard against insufficient sample size (minimum 2 samples required)
if
(m_buffer_count <
2
)
     {
      mean    =
0.0
;
      std_dev =
0.0
;
return
;
     }
//--- Compute arithmetic sample mean
double
sum =
0.0
;
for
(
int
i =
0
; i < m_buffer_count; i++)
     {
      sum += (
double
)m_spread_buffer[i];
     }
   mean = sum / m_buffer_count;
//--- Compute sum of squared differences
double
sum_sq_diff =
0.0
;
for
(
int
i =
0
; i < m_buffer_count; i++)
     {
double
diff = (
double
)m_spread_buffer[i] - mean;
      sum_sq_diff += diff * diff;
     }
//--- Compute sample standard deviation (N - 1 degrees of freedom)
std_dev =
MathSqrt
(sum_sq_diff / (m_buffer_count -
1
));
  }
3. Broker Order Filling Policy Resolution
To avoid server rejections with retcode 10030 (TRADE_RETCODE_INVALID_FILL), ResolveFillingMode inspects both SYMBOL_FILLING_MODE and the symbol execution model SYMBOL_TRADE_EXEMODE. When a symbol operates under SYMBOL_TRADE_EXECUTION_MARKET, ORDER_FILLING_RETURN is not supported; therefore, the method verifies that either SYMBOL_FILLING_FOK or SYMBOL_FILLING_IOC is explicitly enabled and returns false if no valid mode is available:
//+------------------------------------------------------------------+
//| Resolves compliant order filling policy                          |
//+------------------------------------------------------------------+
bool
CExecutionFilter::ResolveFillingMode(
ENUM_ORDER_TYPE_FILLING
&filling)
const
{
//--- Query broker symbol filling mode flags
long
raw_filling =
0
;
if
(!
SymbolInfoInteger
(m_symbol,
SYMBOL_FILLING_MODE
, raw_filling))
     {
      filling =
ORDER_FILLING_RETURN
;
return
false
;
     }
//--- Query execution mode to prevent invalid return filling on market execution
long
raw_exe_mode =
0
;
if
(!
SymbolInfoInteger
(m_symbol,
SYMBOL_TRADE_EXEMODE
, raw_exe_mode))
     {
      filling =
ORDER_FILLING_RETURN
;
return
false
;
     }
uint
filling_mode = (
uint
)raw_filling;
ENUM_SYMBOL_TRADE_EXECUTION
exe_mode = (
ENUM_SYMBOL_TRADE_EXECUTION
)raw_exe_mode;
//--- Check Fill or Kill (FOK) support
if
((filling_mode &
SYMBOL_FILLING_FOK
) !=
0
)
     {
      filling =
ORDER_FILLING_FOK
;
return
true
;
     }
//--- Check Immediate or Cancel (IOC) support
if
((filling_mode &
SYMBOL_FILLING_IOC
) !=
0
)
     {
      filling =
ORDER_FILLING_IOC
;
return
true
;
     }
//--- Evaluate Return policy for exchange, instant, or request execution regimes
if
(exe_mode !=
SYMBOL_TRADE_EXECUTION_MARKET
)
     {
      filling =
ORDER_FILLING_RETURN
;
return
true
;
     }
//--- Market execution mode requires explicit FOK or IOC support
filling =
ORDER_FILLING_RETURN
;
return
false
;
  }
4. Pre-Trade Execution Pipeline Evaluation
The EvaluateAll method coordinates the five sequential safety checks before an order is sent. It checks tick availability and freshness via time_msc (using MathMax to prevent negative delta underflow), validates server time against the rollover freeze window via TimeTradeServer(), confirms filling mode compatibility, enforces the absolute spread hard cap, and evaluates the statistical Z-score once at least 10 approved samples are present and baseline_std > 0.0. Candidate spreads are tested before updating the ring buffer so that rejected spikes do not contaminate the rolling baseline:
//+------------------------------------------------------------------+
//| Executes pre-trade gating pipeline                               |
//+------------------------------------------------------------------+
bool
CExecutionFilter::EvaluateAll(ExecutionGateReport &report)
  {
   m_telemetry.evaluations_total++;
//--- Initialize diagnostic report default state
report.status           = GATE_STATUS_ALLOWED;
   report.current_spread   =
0
;
   report.baseline_mean    =
0.0
;
   report.baseline_std     =
0.0
;
   report.z_score          =
0.0
;
   report.quote_time_msc   =
0
;
   report.quote_age_ms     =
0
;
   report.resolved_filling =
ORDER_FILLING_RETURN
;
   report.rejection_reason =
"Execution permitted"
;
//--- Gate 1: Live quote availability and freshness
MqlTick
last_tick;
if
(!
SymbolInfoTick
(m_symbol, last_tick))
     {
//--- Intercept missing tick structure
report.status           = GATE_STATUS_BLOCKED_NO_QUOTE;
      report.rejection_reason =
"Failed to obtain live MqlTick structure"
;
      m_telemetry.blocked_no_quote++;
return
false
;
     }

   report.quote_time_msc = last_tick.time_msc;
if
(m_enable_freshness_gate)
     {
//--- Calculate elapsed age relative to server time (ms)
datetime
server_time =
TimeTradeServer
();
long
delta_ms = (
long
)(server_time *
1000
) - (
long
)last_tick.time_msc;
      report.quote_age_ms = (
uint
)
MathMax
(
0
, delta_ms);
if
(report.quote_age_ms > m_max_quote_age_ms)
        {
//--- Block stale quote feed
report.status           = GATE_STATUS_BLOCKED_STALE_QUOTE;
         report.rejection_reason =
StringFormat
(
"Quote age (%u ms) exceeds freshness limit (%u ms)"
,
                                                report.quote_age_ms, m_max_quote_age_ms);
         m_telemetry.blocked_stale_quote++;
return
false
;
        }
     }
//--- Gate 2: Rollover freeze window
if
(m_enable_rollover_gate)
     {
datetime
current_server =
TimeTradeServer
();
MqlDateTime
dt;
TimeToStruct
(current_server, dt);
int
minute_of_day = (dt.hour *
60
) + dt.min;
bool
inside_rollover =
false
;
if
(m_rollover_start_min > m_rollover_end_min)
        {
//--- Rollover window crosses midnight boundary
inside_rollover = (minute_of_day >= m_rollover_start_min || minute_of_day < m_rollover_end_min);
        }
else
{
//--- Rollover window within current calendar day
inside_rollover = (minute_of_day >= m_rollover_start_min && minute_of_day < m_rollover_end_min);
        }
if
(inside_rollover)
        {
//--- Block execution during rollover clearing
report.status           = GATE_STATUS_BLOCKED_ROLLOVER;
         report.rejection_reason =
StringFormat
(
"Server time (%02d:%02d) is within rollover freeze window (%02d:%02d-%02d:%02d)"
,
                                                dt.hour, dt.min,
                                                m_rollover_start_min /
60
, m_rollover_start_min %
60
,
                                                m_rollover_end_min /
60
, m_rollover_end_min %
60
);
         m_telemetry.blocked_rollover++;
return
false
;
        }
     }
//--- Gate 3: Order filling mode compatibility
if
(m_enable_filling_gate)
     {
if
(!ResolveFillingMode(report.resolved_filling))
        {
//--- Block execution when filling mode resolution fails
report.status           = GATE_STATUS_BLOCKED_FILLING;
         report.rejection_reason =
"Unable to resolve a valid broker filling mode for current execution model"
;
         m_telemetry.blocked_filling++;
return
false
;
        }
     }
else
{
      ResolveFillingMode(report.resolved_filling);
     }
//--- Query live market spread
long
spread_val =
0
;
if
(!
SymbolInfoInteger
(m_symbol,
SYMBOL_SPREAD
, spread_val))
     {
//--- Intercept missing spread info
report.status           = GATE_STATUS_BLOCKED_NO_QUOTE;
      report.rejection_reason =
"Failed to query current SYMBOL_SPREAD"
;
      m_telemetry.blocked_no_quote++;
return
false
;
     }
   report.current_spread = spread_val;
//--- Gate 4: Spread hard cap
if
(m_enable_spread_gate && report.current_spread > m_spread_hard_cap)
     {
//--- Block execution when spread exceeds absolute ceiling
report.status           = GATE_STATUS_BLOCKED_SPREAD_HARDCAP;
      report.rejection_reason =
StringFormat
(
"Spread (%d pt) exceeds absolute ceiling (%d pt)"
,
                                             report.current_spread, m_spread_hard_cap);
      m_telemetry.blocked_spread_hardcap++;
return
false
;
     }
//--- Gate 5: Statistical spread anomaly (Z-score, requires minimum 10 samples)
if
(m_enable_spread_gate && m_buffer_count >=
10
)
     {
      ComputeSpreadStats(report.baseline_mean, report.baseline_std);
//--- Skip Z-score check when sample standard deviation is zero
if
(report.baseline_std >
0.0
)
        {
         report.z_score = (report.current_spread - report.baseline_mean) / report.baseline_std;
if
(report.z_score > m_spread_zscore_limit)
           {
//--- Block execution when spread is an outlier
report.status           = GATE_STATUS_BLOCKED_SPREAD_ANOMALY;
            report.rejection_reason =
StringFormat
(
"Spread (%d pt) exceeds Z-score threshold (Z=%.2f, Mean=%.1f, Std=%.1f)"
,
                                                   report.current_spread, report.z_score, report.baseline_mean, report.baseline_std);
            m_telemetry.blocked_spread_anomaly++;
return
false
;
           }
        }
     }
//--- Record verified non-anomalous spread observation
UpdateSpreadBuffer(report.current_spread);

   m_telemetry.signals_approved++;
return
true
;
  }
5. Dynamic Configuration and Telemetry Controls
The configuration methods allow an Expert Advisor to adjust rollover boundaries in minutes from midnight (0–1439) and reset telemetry counters between test runs or trading sessions:
