CExecutionFilter::SetRolloverWindow(
const
int
start_min,
const
int
end_min)
  {
//--- Clamp minute values to valid daily range
m_rollover_start_min = (start_min >=
0
&& start_min <
1440
) ? start_min :
1425
;
   m_rollover_end_min   = (end_min >=
0
&& end_min <
1440
) ? end_min :
15
;
